function modelForm(x={}){const c=x.config||{},custom=Object.fromEntries(Object.entries(c).filter(([key])=>!['timeout','retry','max_retries','concurrency','temperature','max_tokens'].includes(key)));return field('name','名称',x.name,'text','required')+`<div class="field-row">${selectField('model_kind','模型类型',[['llm','大模型'],['embedding','向量模型'],['reranker','重排模型'],['vision','视觉模型'],['asr','语音模型']],x.model_kind||'llm')}${selectField('provider','供应商',[['kimi','Kimi'],['openai','OpenAI'],['openai_compatible','OpenAI 兼容'],['groq','Groq'],['litellm','LiteLLM'],['huggingface','HuggingFace'],['bge','BGE'],['fastembed','FastEmbed']],x.provider||'kimi')}</div>`+field('model_name','模型标识',x.model_name,'text','required')+field('base_url','API 地址',x.base_url||'')+field('api_key','API Key','','password',x.id?'placeholder="留空保持不变"':'')+`<div class="field-row">${field('timeout','超时（秒）',c.timeout??60,'number','required min="1" max="3600"')}${field('retry','重试次数',c.retry??c.max_retries??2,'number','required min="0" max="10"')}</div><div class="field-row">${field('concurrency','并发数',c.concurrency??4,'number','required min="1" max="100"')}${field('temperature','温度',c.temperature??0.2,'number','required min="0" max="2" step="0.01"')}${field('max_tokens','最大 Token',c.max_tokens??4096,'number','required min="1" max="200000"')}</div>`+area('custom_config','自定义参数',custom,true)+`<div class="field-row">${check('enabled','启用',x.enabled??true)}${check('is_default','设为默认',x.is_default||false)}</div>`}
async function editModel(x){const ok=await modal(x?'编辑模型':'新增模型',modelForm(x),async d=>{d.config={...(d.custom_config||{}),timeout:Number(d.timeout),retry:Number(d.retry),concurrency:Number(d.concurrency),temperature:Number(d.temperature),max_tokens:Number(d.max_tokens)};['custom_config','timeout','retry','concurrency','temperature','max_tokens'].forEach(key=>delete d[key]);if(!d.api_key)delete d.api_key;await api(x?`/model-configs/${x.id}`:'/model-configs',{method:x?'PUT':'POST',body:d})});if(ok){toast('已保存');renderModels()}}
