const ADVANCED_SOURCE_TYPES=Object.keys(SOURCE_TYPE_NAMES).filter(x=>!CORE_SOURCE_TYPES.includes(x));
const SOURCE_CONFIG_DEFAULTS={google_drive:{folder_id:'root',recursive:true,max_files:500},mongodb:{host:'mongodb.example.com',port:27017,database:'knowledge',collection:'documents',username:'',auth_database:'admin',limit:1000},elasticsearch:{url:'https://search.example.com',index:'knowledge',username:'',limit:1000,verify_certs:true},opensearch:{url:'https://search.example.com',index:'knowledge',username:'',limit:1000,verify_certs:true},duckdb:{path:'/app/data/sources/data.parquet',limit:1000,memory_limit:'1GB'},parquet:{path:'/app/data/sources/data.parquet',limit:1000},arrow:{path:'/app/data/sources/data.arrow',limit:1000},huggingface:{dataset:'',split:'train',limit:1000},stream:{stream_type:'rabbitmq',host:'rabbitmq',port:5672,username:'semantica',vhost:'/',queue:'knowledge-ingest',max_messages:100,durable:true},snowflake:{account:'',username:'',warehouse:'',database:'',schema:'PUBLIC',table:'',limit:1000},databricks:{host:'',http_path:'',catalog:'main',schema:'default',table:'',limit:1000},local_dir:{path:'/app/data/sources',recursive:true,max_files:5000},s3:{endpoint:'minio:9000',bucket:'knowledge',prefix:'',access_key:'semantica',secure:false,max_files:5000},object_prefix:{endpoint:'minio:9000',bucket:'knowledge',prefix:'',access_key:'semantica',secure:false,max_files:5000},sftp:{host:'',port:22,username:'',path:'.',recursive:true,max_files:5000},ftp:{host:'',port:21,username:'anonymous',path:'/',recursive:true,max_files:5000},ftps:{host:'',port:21,username:'',path:'/',recursive:true,max_files:5000},webdav:{url:'https://dav.example.com/knowledge/',username:'',timeout:30,max_files:5000},smb:{server:'',port:445,share:'knowledge',path:'',username:'',recursive:true,max_files:5000},onedrive:{drive_id:'me',path:'',recursive:true,max_files:5000},sharepoint:{site_id:'',drive_id:'',path:'',recursive:true,max_files:5000}};
const sourceTypeName=type=>SOURCE_TYPE_NAMES[type]||type;
function sourceLogo(type){const icon=SOURCE_TYPE_META[type]?.icon??29,col=icon%5,row=Math.floor(icon/5);return `<span class="source-logo" aria-hidden="true" style="background-position:${col*25}% ${row*20}%"></span>`}
function sourcePicker(){return `<label class="source-picker-search"><span>搜索</span><input id="source-type-search" type="search" placeholder="搜索数据源" autocomplete="off"></label><div class="source-category-list">${SOURCE_CATEGORIES.map(([label,types])=>`<section class="source-category"><h4>${label}</h4><div class="source-type-grid">${types.map(type=>`<label class="source-type-card" data-source-type-card data-search="${esc(`${sourceTypeName(type)} ${SOURCE_TYPE_META[type]?.hint||''}`.toLowerCase())}"><input type="radio" name="source_type" value="${type}" required>${sourceLogo(type)}<span><b>${esc(sourceTypeName(type))}</b><small>${esc(SOURCE_TYPE_META[type]?.hint||'')}</small></span><i>✓</i></label>`).join('')}</div></section>`).join('')}</div>`}
async function chooseSourceType(){let selected='';const dlg=$('#modal');dlg.classList.add('source-picker-modal');try{const ok=await modal('选择数据源类型',sourcePicker(),async d=>{selected=d.source_type},'下一步',form=>{const cards=[...form.querySelectorAll('[data-source-type-card]')];const refresh=()=>cards.forEach(card=>card.classList.toggle('selected',card.querySelector('input').checked));cards.forEach(card=>card.onchange=refresh);form.querySelector('#source-type-search').oninput=e=>{const term=e.target.value.trim().toLowerCase();cards.forEach(card=>card.classList.toggle('hidden',Boolean(term&&!card.dataset.search.includes(term))));form.querySelectorAll('.source-category').forEach(section=>section.classList.toggle('hidden',![...section.querySelectorAll('[data-source-type-card]')].some(card=>!card.classList.contains('hidden'))))}});dlg.classList.remove('source-picker-modal');if(ok&&selected){await new Promise(resolve=>requestAnimationFrame(()=>resolve()));await editSource(null,selected)}}finally{dlg.classList.remove('source-picker-modal')}}
function sourceForm(x={}){const c=x.config||{},type=x.source_type||'web';return `${x.id?`<input type="hidden" name="source_record_id" value="${esc(x.id)}">`:''}<input type="hidden" name="source_type" value="${esc(type)}"><div class="source-config-type">${sourceLogo(type)}<span><small>数据源类型</small><b>${esc(sourceTypeName(type))}</b></span></div>${field('source_name','名称',x.name,'text','required autocomplete="off"')}`+selectField('space_id','知识空间',state.spaces.map(s=>[s.id,s.name]),x.space_id||'','required')+
`<div data-source-fields="web">${field('web_url','网页地址',c.url||'https://httpbin.org/html','url','required')}<div class="field-row">${field('web_delay','请求间隔（秒）',c.delay??0.2,'number','min="0" max="60" step="0.1"')}${field('web_timeout','超时（秒）',c.timeout??30,'number','min="1" max="120"')}</div><div class="field-row">${field('web_retries','失败重试',c.max_retries??3,'number','min="0" max="10"')}${check('web_respect_robots','遵守 robots.txt',c.respect_robots??true)}</div></div>`+
`<div data-source-fields="rest">${field('rest_url','接口地址',c.url||'https://httpbin.org/anything','url','required')}<div class="field-row">${selectField('rest_method','请求方法',[['GET','GET'],['POST','POST']],c.method||'GET')}${field('rest_timeout','超时（秒）',c.timeout??30,'number','min="1" max="120"')}</div>${area('rest_headers','请求头（JSON）',c.headers||{},true)}${area('rest_params','查询参数（JSON）',c.params||{},true)}${area('rest_body','请求体（JSON，仅 POST）',c.body||{},true)}<div class="field-row">${field('rest_secret_header','密钥请求头',c.secret_header||'Authorization')}${field('rest_secret_prefix','密钥前缀',c.secret_prefix??'Bearer ')}</div>${field('rest_retries','失败重试',c.max_retries??3,'number','min="0" max="10"')}</div>`+
`<div data-source-fields="rss">${field('rss_url','Feed 地址',c.url||'','url','required')}<div class="field-row">${field('rss_max_items','最多条目',c.max_items??100,'number','min="1" max="1000"')}${field('rss_timeout','超时（秒）',c.timeout??30,'number','min="1" max="120"')}</div></div>`+
`<div data-source-fields="sitemap">${field('sitemap_url','Sitemap 地址',c.url||'','url','required')}<div class="field-row">${field('sitemap_max_urls','最多页面',c.max_urls??50,'number','min="1" max="1000"')}${field('sitemap_delay','请求间隔（秒）',c.delay??0.2,'number','min="0" max="60" step="0.1"')}</div><div class="field-row">${field('sitemap_pattern','包含规则',c.pattern||'')}${field('sitemap_exclude','排除规则',c.exclude_pattern||'')}</div></div>`+
`<div data-source-fields="git">${field('git_url','仓库地址',c.url||'https://github.com/semantica-agi/semantica','url','required')}<div class="field-row">${field('git_branch','分支',c.branch||'')}${field('git_depth','克隆深度',c.depth??1,'number','min="1" max="100"')}</div><label class="field"><span>文件扩展名（逗号分隔）</span><input name="git_extensions__list" value="${esc((c.include_extensions||['md','txt','py','js','ts']).join(', '))}"></label>${check('git_history','读取提交历史',c.include_history||false)}</div>`+
`<div data-source-fields="database"><div class="field-row">${selectField('db_dialect','数据库',[['postgresql','PostgreSQL'],['mysql','MySQL']],c.dialect||'postgresql')}${field('db_host','主机',c.host||'','text','required')}</div><div class="field-row">${field('db_port','端口',c.port||5432,'number','min="1" max="65535"')}${field('db_name','数据库名',c.database||'','text','required')}</div>${field('db_user','用户名',c.username||'','text','required')}<label class="field"><span>包含表（逗号分隔，留空为全部）</span><input name="db_tables__list" value="${esc((c.include_tables||[]).join(', '))}"></label>${field('db_max_rows','每表最多行',c.max_rows_per_table??1000,'number','min="1" max="100000"')}</div>`+
`<div data-source-fields="email"><div class="field-row">${selectField('mail_protocol','协议',[['imap','IMAP'],['pop3','POP3']],c.protocol||'imap')}${field('mail_server','服务器',c.server||'','text','required')}</div><div class="field-row">${field('mail_port','端口',c.port||(c.protocol==='pop3'?995:993),'number','min="1" max="65535"')}${field('mail_user','用户名',c.username||'','text','required')}</div><div class="field-row">${field('mail_box','邮箱目录',c.mailbox||'INBOX')}${field('mail_max','最多邮件',c.max_emails??100,'number','min="1" max="1000"')}</div><div class="field-row">${field('mail_since','起始日期',c.since||'')}${check('mail_unread','仅未读',c.unread_only||false)}</div></div>`+
`<div data-source-fields="mcp">${field('mcp_url','MCP 地址',c.url||'','url','required')}<div class="field-row">${field('mcp_name','服务器名称',c.server_name||x.name||'knowledge')}${field('mcp_timeout','超时（秒）',c.timeout??30,'number','min="1" max="120"')}</div>${area('mcp_headers','请求头（JSON）',c.headers||{},true)}<div class="field-row">${field('mcp_secret_header','密钥请求头',c.secret_header||'Authorization')}${field('mcp_secret_prefix','密钥前缀',c.secret_prefix??'Bearer ')}</div></div>`+
`<div data-source-fields="${ADVANCED_SOURCE_TYPES.join(',')}">${area('advanced_config','连接参数',ADVANCED_SOURCE_TYPES.includes(type)?(x.id?Object.fromEntries(Object.entries(c).filter(([k])=>k!=='schedule_minutes')):(SOURCE_CONFIG_DEFAULTS[type]||{})):{},true)}</div>`+
`<div class="field-row">${field('schedule_minutes','同步周期（分钟，0 为关闭）',c.schedule_minutes??0,'number','min="0" max="10080"')}${field('source_secret','访问密钥 / 密码','','password',(x.id?'placeholder="留空保持不变" ':'')+'autocomplete="new-password"')}</div>`+(x.id?check('clear_secret','清除已保存密钥',false):'')+`<div class="field-row">${check('enabled','启用',x.enabled??true)}<div class="source-test-row"><button type="button" class="secondary" id="source-test">测试连接</button><span id="source-test-result" class="muted"></span></div></div>`}
function toggleSourceFields(form){const type=form.querySelector('[name=source_type]').value;form.querySelectorAll('[data-source-fields]').forEach(block=>{const active=block.dataset.sourceFields.split(',').includes(type);block.classList.toggle('hidden',!active);block.querySelectorAll('input,select,textarea').forEach(control=>control.disabled=!active)})}
function sourcePayloadFromForm(d,x,forTest=false){let config={schedule_minutes:Number(d.schedule_minutes||0)};if(ADVANCED_SOURCE_TYPES.includes(d.source_type))config={...(d.advanced_config||{}),schedule_minutes:Number(d.schedule_minutes||0)};if(d.source_type==='web')Object.assign(config,{url:d.web_url,delay:Number(d.web_delay),timeout:Number(d.web_timeout),max_retries:Number(d.web_retries),respect_robots:Boolean(d.web_respect_robots)});if(d.source_type==='rest'){Object.assign(config,{url:d.rest_url,method:d.rest_method,timeout:Number(d.rest_timeout),max_retries:Number(d.rest_retries),headers:d.rest_headers||{},params:d.rest_params||{},secret_header:d.rest_secret_header,secret_prefix:d.rest_secret_prefix});if(d.rest_method==='POST')config.body=d.rest_body||{}}if(d.source_type==='rss')Object.assign(config,{url:d.rss_url,max_items:Number(d.rss_max_items),timeout:Number(d.rss_timeout),validate:true});if(d.source_type==='sitemap')Object.assign(config,{url:d.sitemap_url,max_urls:Number(d.sitemap_max_urls),delay:Number(d.sitemap_delay),pattern:d.sitemap_pattern||null,exclude_pattern:d.sitemap_exclude||null,respect_robots:true});if(d.source_type==='git')Object.assign(config,{url:d.git_url,branch:d.git_branch||null,depth:Number(d.git_depth),include_extensions:d.git_extensions||[],include_history:Boolean(d.git_history)});if(d.source_type==='database')Object.assign(config,{dialect:d.db_dialect,host:d.db_host,port:Number(d.db_port),database:d.db_name,username:d.db_user,include_tables:d.db_tables||[],max_rows_per_table:Number(d.db_max_rows)});if(d.source_type==='email')Object.assign(config,{protocol:d.mail_protocol,server:d.mail_server,port:Number(d.mail_port),username:d.mail_user,mailbox:d.mail_box,max_emails:Number(d.mail_max),since:d.mail_since||null,unread_only:Boolean(d.mail_unread)});if(d.source_type==='mcp')Object.assign(config,{url:d.mcp_url,server_name:d.mcp_name,timeout:Number(d.mcp_timeout),headers:d.mcp_headers||{},secret_header:d.mcp_secret_header,secret_prefix:d.mcp_secret_prefix});const payload={space_id:d.space_id,source_type:d.source_type,config};if(forTest&&x?.id)payload.source_id=x.id;if(!forTest){payload.name=d.source_name.trim();payload.enabled=Boolean(d.enabled)}if(d.source_secret)payload.secret=d.source_secret;if(d.clear_secret)payload.clear_secret=true;return payload}
async function testSourceForm(form,x){const button=form.querySelector('#source-test'),result=form.querySelector('#source-test-result');button.disabled=true;result.className='muted';result.textContent='检测中';try{const out=await api('/sources/test',{method:'POST',body:sourcePayloadFromForm(formData(form),x,true)});result.textContent=`成功 · HTTP ${out.status_code||'—'} · ${out.elapsed_ms} ms`;toast('连接成功')}catch(err){result.className='error-inline';result.textContent=err.message;toast(err.message,true)}finally{button.disabled=false}}
async function editSource(x,selectedType=''){const record=x||{source_type:selectedType};const editing=Boolean(x?.id);const ok=await modal(editing?'编辑数据源':`配置 · ${sourceTypeName(record.source_type)}`,sourceForm(record),async d=>api(editing?`/sources/${x.id}`:'/sources',{method:editing?'PUT':'POST',body:sourcePayloadFromForm(d,x)}),'保存',form=>{toggleSourceFields(form);form.querySelector('#source-test').onclick=()=>testSourceForm(form,x)});if(ok){toast('已保存');renderSources()}}
async function testSavedSource(source,button){button.disabled=true;toast('正在测试连接');try{const out=await api('/sources/test',{method:'POST',body:{source_id:source.id,space_id:source.space_id,source_type:source.source_type,config:source.config}});toast(`连接成功 · ${out.elapsed_ms} ms`)}catch(err){toast(err.message,true)}finally{button.disabled=false}}
async function viewSource(x){if(state.sourcesTimer){clearTimeout(state.sourcesTimer);state.sourcesTimer=null}state.sourceDetailId=x.id;const out=await api(`/sources/${x.id}/jobs`);const s=out.source,names=Object.fromEntries(state.spaces.map(v=>[v.id,v.name]));actions('<button class="secondary" id="source-back">数据源列表</button><button id="source-refresh">刷新</button>');page(`数据源 · ${s.name}`,`<div class="panel"><div class="source-summary"><div><span>类型</span><b>${esc(sourceTypeName(s.source_type))}</b></div><div><span>知识空间</span><b>${esc(names[s.space_id]||s.space_id)}</b></div><div><span>同步文档</span><b>${s.document_count||0}</b></div><div><span>最近结果</span>${status(s.syncing?'running':s.last_sync_status)}</div></div><div class="toolbar"><button type="button" id="source-run" ${s.syncing?'disabled':''}>${s.syncing?'同步中':'立即同步'}</button><button type="button" class="secondary" id="source-test-saved">测试连接</button><span class="grow"></span><span class="mono muted truncate">${esc(s.config?.url||s.config?.host||s.config?.server||s.config?.endpoint||s.config?.path||'—')}</span></div></div>${table(['开始时间','状态','进度','结束时间','结果','错误','操作'],out.items.map(j=>`<tr><td>${fmtDate(j.started_at||j.created_at)}</td><td>${status(j.status)}</td><td>${progress(j.progress)}</td><td>${fmtDate(j.finished_at)}</td><td class="truncate mono">${esc(JSON.stringify(j.result||{}))}</td><td class="truncate">${esc(j.error_message||'—')}</td><td class="actions">${btn('详情','source-job-view',j.id)}${j.status==='failed'?btn('重试','source-job-retry',j.id):''}</td></tr>`))}`);$('#source-back').onclick=renderSources;$('#source-refresh').onclick=()=>viewSource(s);$('#source-run').onclick=async e=>{e.currentTarget.disabled=true;try{await api(`/sources/${s.id}/sync`,{method:'POST'});toast('同步任务已提交');viewSource(s)}catch(err){e.currentTarget.disabled=false;toast(err.message,true)}};$('#source-test-saved').onclick=e=>testSavedSource(s,e.currentTarget);$('#content').onclick=async e=>{const b=e.target.closest('[data-action]');if(!b)return;if(b.dataset.action==='source-job-view')viewJob(b.dataset.id);if(b.dataset.action==='source-job-retry'){try{await api(`/jobs/${b.dataset.id}/retry`,{method:'POST'});toast('已重新提交');viewSource(s)}catch(err){toast(err.message,true)}}};if(out.items.some(j=>['queued','running'].includes(j.status)))state.sourcesTimer=setTimeout(()=>{if(state.view==='sources'&&state.sourceDetailId===s.id&&!$('#modal').open)viewSource(s)},2000)}

async function renderDocumentJobs(){
  if(state.jobsTimer){clearTimeout(state.jobsTimer);state.jobsTimer=null}state.documentsMode='jobs';const standalone=state.view==='jobs';
  actions(`${standalone?'':'<button class="secondary" id="jobs-back">文档列表</button>'}<button id="jobs-refresh">刷新</button>`);const rows=await api('/jobs');
  page(standalone?'任务中心':'文档 · 任务',table(['类型','任务对象','状态','阶段进度','创建时间','结束时间','错误','操作'],rows.map(x=>`<tr><td>${esc(x.job_type)}</td><td class="truncate">${esc(x.target_name||'—')}</td><td>${status(x.status)}</td><td>${progress(x.progress)}</td><td>${fmtDate(x.created_at)}</td><td>${fmtDate(x.finished_at)}</td><td class="truncate">${esc(x.error_message||'—')}</td><td class="actions">${btn('详情','job-view',x.id)}${x.status==='failed'?btn('重试','job-retry',x.id):''}${state.user.is_admin&&!['queued','running'].includes(x.status)?btn('删除','job-delete',x.id,'danger'):''}</td></tr>`)));
  if(!standalone)$('#jobs-back').onclick=renderDocuments;$('#jobs-refresh').onclick=renderDocumentJobs;$('#content').onclick=async e=>{const b=e.target.closest('[data-action]');if(!b)return;try{if(b.dataset.action==='job-view')viewJob(b.dataset.id);if(b.dataset.action==='job-retry'){await api(`/jobs/${b.dataset.id}/retry`,{method:'POST'});toast('已重新提交');renderDocumentJobs()}if(b.dataset.action==='job-delete'&&confirm('删除该任务记录？')){await api(`/jobs/${b.dataset.id}`,{method:'DELETE'});renderDocumentJobs()}}catch(err){toast(err.message,true)}};
  if(rows.some(x=>['queued','running'].includes(x.status)))state.jobsTimer=setTimeout(()=>{if(['documents','jobs'].includes(state.view)&&state.documentsMode==='jobs'&&!$('#modal').open)renderDocumentJobs()},2000);
}
async function viewJob(id){const x=await api(`/jobs/${id}`);await modal('任务详情',`<div class="detail-grid"><span>任务 ID</span><code>${esc(x.id)}</code><span>任务对象</span><span>${esc(x.target_name||'—')}</span><span>状态</span><span>${status(x.status)}</span><span>阶段进度</span><span class="progress-wide">${progress(x.progress)}</span><span>输入</span><pre>${esc(JSON.stringify(x.input,null,2))}</pre><span>结果</span><pre>${esc(JSON.stringify(x.result,null,2))}</pre><span>错误</span><span>${esc(x.error_message||'—')}</span></div>`+table(['步骤','状态','开始','结束','详情'],x.steps.map(s=>`<tr><td>${esc(s.name)}</td><td>${status(s.status)}</td><td>${fmtDate(s.started_at)}</td><td>${fmtDate(s.finished_at)}</td><td class="mono">${esc(JSON.stringify(s.detail))}</td></tr>`)),async()=>{},'关闭')}

async function renderProcessingPolicies(){
  actions('<button class="secondary" id="chunk-add">新增切片</button><button class="secondary" id="extract-add">新增抽取</button><button id="govern-add">新增治理</button>');
  const [chunks,extracts,governs,models]=await Promise.all([api('/chunk-policies'),api('/extraction-policies'),api('/governance-policies'),api('/model-configs')]);state.models=models;
  const modelNames=Object.fromEntries(models.map(x=>[x.id,x.name]));
  page('加工策略',`<h3 class="section-title">切片</h3>${table(['名称','方法','长度','重叠','版本','默认','操作'],chunks.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.method)}</td><td>${x.chunk_size}</td><td>${x.chunk_overlap}</td><td>V${x.policy_version}</td><td>${x.is_default?'是':'—'}</td><td class="actions">${btn('编辑','chunk-edit',x.id)}${btn('删除','chunk-delete',x.id,'danger')}</td></tr>`))}<h3 class="section-title">语义抽取</h3>${table(['名称','模型','置信度','最多切片','版本','默认','操作'],extracts.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(modelNames[x.model_config_id]||'—')}</td><td>${x.min_confidence}</td><td>${x.max_chunks}</td><td>V${x.policy_version}</td><td>${x.is_default?'是':'—'}</td><td class="actions">${btn('编辑','extract-edit',x.id)}${btn('删除','extract-delete',x.id,'danger')}</td></tr>`))}<h3 class="section-title">自动治理</h3>${table(['名称','相似度','发布阈值','冲突策略','版本','默认','操作'],governs.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.similarity_threshold}</td><td>${x.publish_confidence}</td><td>${esc(x.conflict_strategy)}</td><td>V${x.policy_version}</td><td>${x.is_default?'是':'—'}</td><td class="actions">${btn('编辑','govern-edit',x.id)}${btn('删除','govern-delete',x.id,'danger')}</td></tr>`))}`);
  $('#chunk-add').onclick=()=>editChunkPolicy();$('#extract-add').onclick=()=>editExtractionPolicy();$('#govern-add').onclick=()=>editGovernancePolicy();
  $('#content').onclick=async e=>{const b=e.target.closest('[data-action]');if(!b)return;const [kind,action]=b.dataset.action.split('-');const rows={chunk:chunks,extract:extracts,govern:governs}[kind];const x=rows?.find(v=>v.id===b.dataset.id);try{if(action==='edit'){if(kind==='chunk')editChunkPolicy(x);if(kind==='extract')editExtractionPolicy(x);if(kind==='govern')editGovernancePolicy(x)}if(action==='delete'&&confirm(`删除 ${x.name}？`)){await api(`/${kind==='chunk'?'chunk-policies':kind==='extract'?'extraction-policies':'governance-policies'}/${x.id}`,{method:'DELETE'});renderProcessingPolicies()}}catch(err){toast(err.message,true)}};
}
async function editChunkPolicy(x){const body=field('name','名称',x?.name||'','text','required')+`<div class="field-row">${selectField('method','切片方法',[['recursive','递归'],['sentence','句子'],['paragraph','段落'],['token','Token'],['semantic','语义']],x?.method||'recursive')}${field('chunk_size','切片长度',x?.chunk_size??800,'number','min="100" max="10000"')}</div>`+field('chunk_overlap','重叠长度',x?.chunk_overlap??120,'number','min="0" max="5000"')+area('config','附加参数',x?.config||{},true)+`<div class="field-row">${check('enabled','启用',x?.enabled??true)}${check('is_default','默认',x?.is_default||false)}</div>`;const ok=await modal(x?'编辑切片策略':'新增切片策略',body,async d=>{d.chunk_size=Number(d.chunk_size);d.chunk_overlap=Number(d.chunk_overlap);await api(x?`/chunk-policies/${x.id}`:'/chunk-policies',{method:x?'PUT':'POST',body:d})});if(ok){toast('已保存');renderProcessingPolicies()}}
async function editExtractionPolicy(x){const llms=state.models.filter(m=>m.model_kind==='llm');const body=field('name','名称',x?.name||'','text','required')+selectField('model_config_id','大模型',llms.map(m=>[m.id,m.name]),x?.model_config_id||'','required')+`<div class="field-row">${field('min_confidence','最低置信度',x?.min_confidence??0.65,'number','min="0" max="1" step="0.01"')}${field('max_chunks','最多切片',x?.max_chunks??30,'number','min="1" max="500"')}</div>`+`<label class="field"><span>实体类型（逗号分隔）</span><input name="entity_types__list" value="${esc((x?.entity_types||['组织','人物','产品','地点','时间','指标','制度']).join(', '))}"></label><label class="field"><span>关系类型（逗号分隔）</span><input name="relation_types__list" value="${esc((x?.relation_types||[]).join(', '))}"></label>`+area('config','附加参数',x?.config||{},true)+`<div class="field-row">${check('enabled','启用',x?.enabled??true)}${check('is_default','默认',x?.is_default||false)}</div>`;const ok=await modal(x?'编辑抽取策略':'新增抽取策略',body,async d=>{d.min_confidence=Number(d.min_confidence);d.max_chunks=Number(d.max_chunks);await api(x?`/extraction-policies/${x.id}`:'/extraction-policies',{method:x?'PUT':'POST',body:d})});if(ok){toast('已保存');renderProcessingPolicies()}}
async function editGovernancePolicy(x){const c=x?.config||{},llms=state.models.filter(m=>m.model_kind==='llm');const body=field('name','名称',x?.name||'','text','required')+`<div class="field-row">${field('similarity_threshold','实体相似度',x?.similarity_threshold??0.86,'number','min="0" max="1" step="0.01"')}${field('publish_confidence','发布阈值',x?.publish_confidence??0.72,'number','min="0" max="1" step="0.01"')}</div>`+`<div class="field-row">${selectField('conflict_strategy','冲突策略',[['highest_confidence','最高置信度'],['latest','最新来源'],['keep_all','全部保留']],x?.conflict_strategy||'highest_confidence')}${selectField('profile_model_id','画像模型',opt(llms,'使用抽取模型'),c.model_config_id||'')}</div>`+`<div class="field-row">${field('summary_length','摘要长度',c.summary_length??240,'number','min="50" max="2000"')}${field('tag_count','标签数量',c.tag_count??8,'number','min="1" max="30"')}</div>`+`<label class="field"><span>分类体系（逗号分隔）</span><input name="taxonomy__list" value="${esc((c.taxonomy||['产品资料','制度规范','项目材料','经营分析','会议材料','技术资料','合同法务','其他']).join(', '))}"></label>`+`<div class="field-row">${field('quality_threshold','质量阈值',c.quality_threshold??60,'number','min="0" max="100"')}${field('duplicate_threshold','重复阈值',c.duplicate_threshold??0.2,'number','min="0" max="1" step="0.01"')}</div>`+`<div class="field-row">${selectField('incremental_strategy','增量策略',[['changed_chunks','仅变化切片'],['full','全量重建']],c.incremental_strategy||'changed_chunks')}${field('max_age_days','过期天数',c.max_age_days??365,'number','min="0" max="36500"')}</div>`+area('config_extra','附加参数',c,true)+`<div class="field-row">${check('auto_summary','自动摘要',c.auto_summary??true)}${check('auto_classify','自动分类',c.auto_classify??true)}${check('enable_model_analysis','模型分析',c.enable_model_analysis??true)}</div><div class="field-row">${check('enabled','启用',x?.enabled??true)}${check('is_default','默认',x?.is_default||false)}</div>`;const ok=await modal(x?'编辑治理策略':'新增治理策略',body,async d=>{d.similarity_threshold=Number(d.similarity_threshold);d.publish_confidence=Number(d.publish_confidence);d.config={...(d.config_extra||{}),auto_summary:Boolean(d.auto_summary),auto_classify:Boolean(d.auto_classify),enable_model_analysis:Boolean(d.enable_model_analysis),summary_length:Number(d.summary_length),tag_count:Number(d.tag_count),taxonomy:d.taxonomy||[],quality_threshold:Number(d.quality_threshold),duplicate_threshold:Number(d.duplicate_threshold),incremental_strategy:d.incremental_strategy,max_age_days:Number(d.max_age_days)};if(d.profile_model_id)d.config.model_config_id=d.profile_model_id;else delete d.config.model_config_id;['config_extra','auto_summary','auto_classify','enable_model_analysis','summary_length','tag_count','taxonomy','quality_threshold','duplicate_threshold','incremental_strategy','max_age_days','profile_model_id'].forEach(k=>delete d[k]);await api(x?`/governance-policies/${x.id}`:'/governance-policies',{method:x?'PUT':'POST',body:d})});if(ok){toast('已保存');renderProcessingPolicies()}}

async function renderOntologies(){actions('<button id="ontology-add">新增本体</button>');await refreshLookups();const rows=await api('/ontologies');const spaces=Object.fromEntries(state.spaces.map(x=>[x.id,x.name]));page('本体词表',table(['编码','名称','范围','命名空间','版本','状态','操作'],rows.map(x=>`<tr><td class="mono">${esc(x.code)}</td><td>${esc(x.name)}</td><td>${esc(spaces[x.space_id]||'全集团')}</td><td class="mono truncate">${esc(x.namespace)}</td><td>V${x.version}</td><td>${status(x.enabled?'available':'unavailable')}</td><td class="actions">${btn('词条','ontology-terms',x.id)}${btn('编辑','ontology-edit',x.id)}${btn('删除','ontology-delete',x.id,'danger')}</td></tr>`)));$('#ontology-add').onclick=()=>editOntology();$('#content').onclick=async e=>{const b=e.target.closest('[data-action]');if(!b)return;const x=rows.find(v=>v.id===b.dataset.id);try{if(b.dataset.action==='ontology-terms')renderOntologyTerms(x);if(b.dataset.action==='ontology-edit')editOntology(x);if(b.dataset.action==='ontology-delete'&&confirm(`删除 ${x.name} 及其词条？`)){await api(`/ontologies/${x.id}`,{method:'DELETE'});renderOntologies()}}catch(err){toast(err.message,true)}}}
async function editOntology(x){const body=`<div class="field-row">${field('code','编码',x?.code||'','text','required')}${field('name','名称',x?.name||'','text','required')}</div>`+selectField('space_id','范围',opt(state.spaces,'全集团'),x?.space_id||'')+field('namespace','命名空间',x?.namespace||'urn:guolian:knowledge:','text','required')+area('description','描述',x?.description||'')+area('config','附加参数',x?.config||{},true)+check('enabled','启用',x?.enabled??true);const ok=await modal(x?'编辑本体':'新增本体',body,async d=>{if(!d.space_id)d.space_id=null;await api(x?`/ontologies/${x.id}`:'/ontologies',{method:x?'PUT':'POST',body:d})});if(ok){toast('已保存');renderOntologies()}}
async function renderOntologyTerms(ontology){actions('<button class="secondary" id="term-back">返回</button><button id="term-add">新增词条</button>');const rows=await api(`/ontologies/${ontology.id}/terms`);page(`${ontology.name} · 词条`,table(['编码','名称','类型','上级','别名','状态','操作'],rows.map(x=>`<tr><td class="mono">${esc(x.code)}</td><td>${esc(x.label)}</td><td>${esc(x.term_type)}</td><td>${esc(x.parent_code||'—')}</td><td>${esc((x.aliases||[]).join(', '))}</td><td>${status(x.enabled?'available':'unavailable')}</td><td class="actions">${btn('编辑','term-edit',x.id)}${btn('删除','term-delete',x.id,'danger')}</td></tr>`)));$('#term-back').onclick=renderOntologies;$('#term-add').onclick=()=>editOntologyTerm(ontology);$('#content').onclick=async e=>{const b=e.target.closest('[data-action]');if(!b)return;const x=rows.find(v=>v.id===b.dataset.id);if(b.dataset.action==='term-edit')editOntologyTerm(ontology,x);if(b.dataset.action==='term-delete'&&confirm(`删除 ${x.label}？`)){await api(`/ontology-terms/${x.id}`,{method:'DELETE'});renderOntologyTerms(ontology)}}}
async function editOntologyTerm(ontology,x){const body=`<div class="field-row">${field('code','编码',x?.code||'','text','required')}${field('label','名称',x?.label||'','text','required')}</div>`+`<div class="field-row">${selectField('term_type','类型',[['class','类别'],['property','属性'],['relation','关系'],['event','事件']],x?.term_type||'class')}${field('parent_code','上级编码',x?.parent_code||'')}</div>`+`<label class="field"><span>别名（逗号分隔）</span><input name="aliases__list" value="${esc((x?.aliases||[]).join(', '))}"></label>`+area('definition','定义',x?.definition||'')+area('constraints','约束',x?.constraints||{},true)+check('enabled','启用',x?.enabled??true);const ok=await modal(x?'编辑词条':'新增词条',body,async d=>api(x?`/ontology-terms/${x.id}`:`/ontologies/${ontology.id}/terms`,{method:x?'PUT':'POST',body:d}));if(ok){toast('已保存');renderOntologyTerms(ontology)}}

function graphNodeForm(x={},spaceId=''){
  return `<input type="hidden" name="space_id" value="${esc(spaceId||x.space_id||'')}">`+
    `<div class="field-row">${field('canonical_name','节点名称',x.canonical_name||'','text','required maxlength="500"')}${field('entity_type','节点类型',x.entity_type||'其他','text','required maxlength="100"')}</div>`+
    field('aliases__list','别名（逗号分隔）',(x.aliases||[]).join(', '))+
    area('properties','属性（JSON）',x.properties||{},true)+
    `<div class="field-row">${field('confidence','置信度',x.confidence??1,'number','required min="0" max="1" step="0.01"')}${selectField('status','状态',[['published','已发布'],['staged','暂存'],['rejected','停用']],x.status||'published')}</div>`;
}
function graphEdgeForm(x={},spaceId='',entities=[]){
  const options=entities.map(item=>[item.id,item.canonical_name]);
  return `<input type="hidden" name="space_id" value="${esc(spaceId||x.space_id||'')}">`+
    `<div class="field-row">${selectField('subject_entity_id','主体节点',options,x.subject_entity_id||'','required')}${selectField('object_entity_id','客体节点',options,x.object_entity_id||'','required')}</div>`+
    `<div class="field-row">${field('predicate','关系名称',x.predicate||'','text','required maxlength="200"')}${field('confidence','置信度',x.confidence??1,'number','required min="0" max="1" step="0.01"')}</div>`+
    `<div class="field-row">${selectField('status','状态',[['published','已发布'],['staged','暂存'],['superseded','已替代']],x.status||'published')}${field('valid_from','生效时间',x.valid_from?x.valid_from.slice(0,16):'','datetime-local')}</div>`;
}
async function editGraphNode(x,spaceId){
  const ok=await modal(x?'编辑节点':'新增节点',graphNodeForm(x||{},spaceId),async d=>{
    d.confidence=Number(d.confidence);d.aliases=Array.isArray(d.aliases)?d.aliases:[];await api(x?`/knowledge/entities/${x.id}`:'/knowledge/entities',{method:x?'PUT':'POST',body:d});
  });
  if(ok){toast(x?'节点已更新并发布新图谱':'节点已创建并发布新图谱');renderKnowledge(spaceId)}
}
async function editGraphEdge(x,spaceId,entities){
  if(entities.length<2){toast('至少需要两个节点才能创建关系',true);return}
  const ok=await modal(x?'编辑关系':'新增关系',graphEdgeForm(x||{},spaceId,entities),async d=>{
    d.confidence=Number(d.confidence);d.object_value=null;if(!d.valid_from)d.valid_from=null;
    await api(x?`/knowledge/facts/${x.id}`:'/knowledge/facts',{method:x?'PUT':'POST',body:d});
  });
  if(ok){toast(x?'关系已更新并发布新图谱':'关系已创建并发布新图谱');renderKnowledge(spaceId)}
}
async function curateGraphEntityPair(spaceId,entities){
  if(entities.length<2){toast('至少需要两个节点',true);return}
  const options=entities.map(item=>[item.id,`${item.canonical_name} · ${item.entity_type}`]);
  const ok=await modal('实体合并与拆分',`<div class="field-row">${selectField('left_entity_id','实体 A',options,'','required')}${selectField('right_entity_id','实体 B',options,entities[1]?.id||'','required')}</div>${selectField('operation','治理操作',[['merge','合并为同一实体'],['split','保持为不同实体']],'merge')}${selectField('winner_entity_id','合并后保留',options,'')}${area('reason_note','治理说明','')}`,async d=>{
    if(d.left_entity_id===d.right_entity_id)throw new Error('请选择两个不同实体');if(d.operation==='merge'&&!d.winner_entity_id)d.winner_entity_id=d.left_entity_id;if(d.operation==='split')d.winner_entity_id=null;
    await api('/curation/entities/pair',{method:'POST',body:{space_id:spaceId,...d}});
  });
  if(ok){toast('实体治理发布任务已提交');renderKnowledge(spaceId)}
}
function renderGraphInspector(selection,spaceId,entities,facts){
  const panel=$('#graph-inspector');state.graphSelection=selection;
  if(!selection){panel.innerHTML='<div class="graph-inspector-empty"><span class="graph-orbit-icon">◎</span><b>选择节点或关系</b><small>点击画布中的元素进行查看与编辑</small></div>';return}
  if(selection.kind==='node'){
    const item=entities.find(row=>row.id===selection.id);if(!item)return;
    const related=facts.filter(row=>row.subject_entity_id===item.id||row.object_entity_id===item.id);
    panel.innerHTML=`<div class="graph-inspector-head"><span class="graph-type-dot"></span><div><small>${esc(item.entity_type)}</small><h3>${esc(item.canonical_name)}</h3></div></div><div class="graph-detail-grid"><span>别名</span><b>${esc((item.aliases||[]).join('、')||'—')}</b><span>置信度</span><b>${Number(item.confidence).toFixed(2)}</b><span>关联关系</span><b>${related.length}</b><span>来源</span><b>${item.source_count||0}</b><span>状态</span><b>${status(item.status)}</b></div>${related.length?`<div class="graph-related"><small>关联关系</small>${related.slice(0,12).map(row=>`<button class="graph-related-item" data-graph-edge="${row.id}"><span>${esc(row.predicate)}</span><b>${esc(row.subject_entity_id===item.id?row.object_name:row.subject_name)}</b></button>`).join('')}</div>`:''}<div class="graph-properties"><small>属性</small><pre>${esc(JSON.stringify(item.properties||{},null,2))}</pre></div><div class="graph-inspector-actions"><button id="graph-node-edit">编辑节点</button><button id="graph-node-delete" class="danger">删除节点</button></div>`;
    panel.querySelectorAll('[data-graph-edge]').forEach(button=>button.onclick=()=>state.graph3d.select({kind:'edge',id:button.dataset.graphEdge}));
    $('#graph-node-edit').onclick=()=>editGraphNode(item,spaceId);
    $('#graph-node-delete').onclick=async()=>{if(confirm(`删除节点“${item.canonical_name}”及其关联关系？`)){try{await api(`/knowledge/entities/${item.id}`,{method:'DELETE'});toast('节点已删除并发布新图谱');renderKnowledge(spaceId)}catch(err){toast(err.message,true)}}};
  }else{
    const item=facts.find(row=>row.id===selection.id);if(!item)return;
    const inferred=item.origin_type==='inferred';panel.innerHTML=`<div class="graph-inspector-head edge ${inferred?'inferred':''}"><span class="graph-type-dot"></span><div><small>${inferred?'规则推导':'知识关系'}</small><h3>${esc(item.predicate)}</h3></div></div><div class="graph-relation-flow"><b>${esc(item.subject_name)}</b><span>→</span><b>${esc(item.object_name)}</b></div><div class="graph-detail-grid"><span>置信度</span><b>${Number(item.confidence).toFixed(2)}</b><span>状态</span><b>${status(item.status)}</b><span>生成时间</span><b>${fmtDate(item.published_at||item.created_at)}</b><span>来源类型</span><b>${inferred?'Semantica 规则推导':item.source_chunk_id?'文档抽取':'人工维护'}</b>${inferred?`<span>推理依据</span><b>${esc(item.proof?.rule||'—')}</b>`:''}</div>${inferred?`<div class="graph-inspector-actions"><button id="graph-edge-run">查看推理结果</button></div>`:'<div class="graph-inspector-actions"><button id="graph-edge-edit">编辑关系</button><button id="graph-edge-delete" class="danger">删除关系</button></div>'}`;
    if(inferred){$('#graph-edge-run').onclick=()=>{state.analysisTab='results';go('analysis')}}else{$('#graph-edge-edit').onclick=()=>editGraphEdge(item,spaceId,entities);$('#graph-edge-delete').onclick=async()=>{if(confirm(`删除关系“${item.predicate}”？`)){try{await api(`/knowledge/facts/${item.id}`,{method:'DELETE'});toast('关系已删除并发布新图谱');renderKnowledge(spaceId)}catch(err){toast(err.message,true)}}}}
  }
}
async function renderKnowledge(selected){
  if(state.graph3d){state.graph3d.destroy();state.graph3d=null}
  actions();await refreshLookups();const spaceId=selected||state.spaces[0]?.id;
  if(!spaceId){page('知识图谱','<div class="panel empty">请先创建知识空间</div>');return}
  const [entityResult,factResult,conflicts,releases]=await Promise.all([api(`/knowledge/entities?space_id=${spaceId}&limit=500`),api(`/knowledge/facts?space_id=${spaceId}&limit=500`),api(`/knowledge/conflicts?space_id=${spaceId}`),api(`/knowledge/releases?space_id=${spaceId}`)]);
  const entities=entityResult.items,facts=factResult.items,latest=releases.graphs[0];
  actions('<button id="graph-curate-pair" class="secondary">实体合并 / 拆分</button><button id="graph-add-node" class="secondary">新增节点</button><button id="graph-add-edge">新增关系</button>');
  const types=[...new Set(entities.map(item=>item.entity_type))].slice(0,8);
  page('知识图谱',`<section class="graph-workbench"><div class="graph-toolbar"><div class="graph-space-control">${selectField('knowledge_space','知识空间',state.spaces.map(x=>[x.id,x.name]),spaceId)}</div><div class="graph-search"><input id="graph-search-input" placeholder="搜索并定位节点"><button id="graph-search-button">定位</button></div><div class="graph-camera-tools"><button id="graph-zoom-out" class="secondary" title="缩小">−</button><button id="graph-zoom-in" class="secondary" title="放大">＋</button><button id="graph-reset" class="secondary">适配</button><button id="graph-rotate" class="secondary active">旋转</button></div></div><div class="graph-metrics"><span><b>${entityResult.total}</b> 节点</span><span><b>${factResult.total}</b> 关系</span><span><b>${conflicts.length}</b> 冲突</span><span><b>R${latest?.release_number||0}</b> 当前版本</span></div><div class="graph-body"><div class="graph-stage"><canvas id="knowledge-graph-canvas" tabindex="0" aria-label="3D 知识图谱，可拖拽旋转、滚轮缩放、点击节点或关系编辑"></canvas><div class="graph-scene-badge">3D</div><div class="graph-hint">拖拽旋转 · 滚轮缩放 · 点击编辑</div><div class="graph-legend">${types.map(type=>`<span><i data-entity-type="${esc(type)}"></i>${esc(type)}</span>`).join('')}</div></div><aside id="graph-inspector" class="graph-inspector"></aside></div></section>`);
  const canvas=$('#knowledge-graph-canvas');
  state.graph3d=new window.KnowledgeGraph3D(canvas,{nodes:entities.map(item=>({id:item.id,label:item.canonical_name,type:item.entity_type})),edges:facts.filter(item=>item.object_entity_id).map(item=>({id:item.id,source:item.subject_entity_id,target:item.object_entity_id,label:item.predicate,inferred:item.origin_type==='inferred'}))},{onSelect:selection=>renderGraphInspector(selection,spaceId,entities,facts)});
  renderGraphInspector(null,spaceId,entities,facts);
  $('[name=knowledge_space]').onchange=e=>renderKnowledge(e.target.value);
  $('#graph-curate-pair').onclick=()=>curateGraphEntityPair(spaceId,entities);$('#graph-add-node').onclick=()=>editGraphNode(null,spaceId);$('#graph-add-edge').onclick=()=>editGraphEdge(null,spaceId,entities);
  $('#graph-search-button').onclick=()=>{const hit=state.graph3d.focusByQuery($('#graph-search-input').value);if(!hit)toast('未找到匹配节点',true)};
  $('#graph-search-input').onkeydown=e=>{if(e.key==='Enter'){$('#graph-search-button').click()}};
  $('#graph-zoom-out').onclick=()=>state.graph3d.zoomBy(.82);$('#graph-zoom-in').onclick=()=>state.graph3d.zoomBy(1.2);$('#graph-reset').onclick=()=>state.graph3d.resetView();
  $('#graph-rotate').onclick=e=>{const enabled=state.graph3d.toggleAutoRotate();e.currentTarget.classList.toggle('active',enabled)};
}

function answerHtml(text=''){return esc(text).replace(/\[(\d{1,3})\]/g,'<button class="citation-link" data-citation="$1">[$1]</button>').replace(/\n/g,'<br>')}
function chatMessageHtml(message,events=[]){
  if(message.role==='user')return `<article class="chat-message user"><div class="chat-avatar">我</div><div class="chat-bubble">${esc(message.content).replace(/\n/g,'<br>')}</div></article>`;
  const citations=(message.citations||[]).sort((a,b)=>a.rank-b.rank),traces=message.traces||[],messageEvents=events.filter(x=>x.message_id===message.id),tools=messageEvents.filter(x=>['tool_started','tool_finished'].includes(x.event_type));
  const evidence=citations.length?`<details class="evidence"><summary>召回依据 ${citations.length}</summary><div class="evidence-list">${citations.map(c=>{const x=c.snapshot||{},score=(label,value,always=false)=>value==null&&!always?'':`<em>${label} ${value==null?'—':Number(value).toFixed(4)}</em>`;return `<button class="evidence-card" data-fragment="${esc(c.chunk_id)}"><span class="evidence-rank">${c.rank}</span><span class="evidence-main"><b>${esc(x.title||'未命名文档')}</b><small>${esc((x.snippet||x.text||'').replace(/<[^>]+>/g,'').slice(0,180))}</small><span>${(x.channels||[]).map(v=>`<i>${esc(v)}</i>`).join('')}${score('全文',x.keyword_score,(x.channels||[]).includes('keyword'))}${score('向量',x.vector_score,(x.channels||[]).includes('vector'))}${score('图谱',x.graph_score,(x.channels||[]).includes('graph'))}${score('融合',x.fused_score,true)}${score('重排',x.rerank_score)}</span></span></button>`}).join('')}</div></details>`:'';
  const trace=traces.length||tools.length?`<details class="retrieval-trace"><summary>检索轨迹</summary>${traces.map(t=>{const x=t.trace||{},counts=x.channel_counts||{},timings=x.timings||{};return `<div class="trace-grid"><span>查询</span><b>${esc(x.query||'—')}</b><span>知识空间</span><b>${(x.space_ids||[]).length} 个</b><span>召回</span><b>全文 ${counts.keyword||0} · 向量 ${counts.vector||0} · 图谱 ${counts.graph||0}</b><span>去重</span><b>${x.before_dedup||0} → ${x.after_dedup||0}</b><span>排序</span><b>RRF${x.reranker_applied?' + 重排':''}</b><span>耗时</span><b>${timings.total_ms||t.duration_ms||0} ms</b></div>${(x.warnings||[]).map(w=>`<div class="trace-warning">${esc(w)}</div>`).join('')}`}).join('')}${tools.length?`<div class="tool-trace">${tools.map(x=>`<span>${esc(x.payload?.name||x.event_type)} · ${x.payload?.success===false?'失败':x.event_type.includes('started')?'执行中':'完成'}${x.payload?.duration_ms==null?'':` · ${x.payload.duration_ms} ms`}</span>`).join('')}</div>`:''}</details>`:'';
  const messageActions=message.status==='generating'?'<button class="small secondary chat-stop">停止生成</button>':(['failed','cancelled'].includes(message.status)?`<button class="small secondary chat-retry" data-id="${message.id}">重新生成</button>`:'');
  const emptyAnswer=message.status==='generating'?'<span class="typing">正在生成</span>':message.status==='cancelled'?'<span class="turn-cancelled">已停止生成</span>':message.status==='failed'?'<span class="turn-failed">生成失败</span>':'';
  return `<article class="chat-message assistant" data-message="${message.id}"><div class="chat-avatar">传</div><div class="chat-response"><div class="chat-answer">${message.content?answerHtml(message.content):emptyAnswer}</div>${message.error_message&&message.status!=='cancelled'?`<div class="trace-warning">${esc(message.error_message)}</div>`:''}${trace}${evidence}<div class="chat-message-actions">${messageActions}</div></div></article>`;
}
function renderConversationPane(){
  const c=state.conversation;if(!c){$('#chat-main').innerHTML='<div class="chat-empty"><b>新建会话开始检索</b></div>';return}
  const messages=(c.messages||[]).map(x=>chatMessageHtml(x,c.events||[])).join('');
  $('#chat-main').innerHTML=`<div class="chat-messages">${messages||'<div class="chat-empty"><b>输入问题，开始检索知识</b></div>'}</div><form id="chat-form" class="chat-composer"><textarea name="content" rows="1" placeholder="输入问题，Enter 发送，Shift+Enter 换行" required></textarea><button type="submit" aria-label="发送">发送</button></form>`;
  const box=$('#chat-main .chat-messages');box.scrollTop=box.scrollHeight;
  $('#chat-form').onsubmit=e=>{e.preventDefault();sendChatMessage(e.currentTarget.content.value)};
  $('#chat-form textarea').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();$('#chat-form').requestSubmit()}};
  $('#chat-main').onclick=e=>{const cite=e.target.closest('[data-citation]'),card=e.target.closest('[data-fragment]'),stop=e.target.closest('.chat-stop'),retry=e.target.closest('.chat-retry');if(cite){const messageId=cite.closest('[data-message]')?.dataset.message,row=(c.messages||[]).find(x=>x.id===messageId)?.citations?.find(x=>String(x.citation_number)===cite.dataset.citation);if(row)openFragment(row.chunk_id)}if(card)openFragment(card.dataset.fragment);if(stop)stopChat();if(retry)retryChat(retry.dataset.id)};
}
async function loadConversation(id){state.conversation=await api(`/conversations/${id}`);renderConversationList();renderConversationPane();applyChatSettings()}
function renderConversationList(){const list=$('#conversation-list');if(!list)return;list.innerHTML=state.conversations.map(x=>`<div class="conversation-row ${state.conversation?.id===x.id?'active':''}" data-conversation="${x.id}"><button class="conversation-open"><b>${esc(x.title)}</b><small>${esc(x.last_message||'暂无消息')}</small></button><button class="conversation-more" title="会话操作">•••</button></div>`).join('')||'<div class="conversation-empty">暂无会话</div>'}
async function refreshConversations(selected){const out=await api('/conversations');state.conversations=out.items||[];const id=selected||state.conversation?.id||state.conversations[0]?.id;if(id)await loadConversation(id);else{state.conversation=null;renderConversationList();renderConversationPane()}}
async function newConversation(){const c=await api('/conversations',{method:'POST',body:{title:'新会话',space_ids:state.spaces.map(x=>x.id)}});await refreshConversations(c.id)}
async function conversationMenu(id){
  const c=state.conversations.find(x=>x.id===id);if(!c)return;let deleted=false;
  const body=field('title','会话标题',c.title,'text','required maxlength="200"')+'<div class="conversation-manage-actions"><button type="button" class="secondary" id="conversation-clear">清空消息</button><button type="button" class="danger" id="conversation-delete">删除会话</button></div>';
  const renamed=await modal('会话设置',body,async d=>{await api(`/conversations/${id}`,{method:'PUT',body:{title:d.title.trim()}})},'保存',form=>{
    form.querySelector('#conversation-clear').onclick=async()=>{if(!confirm('清空这个会话的全部消息？'))return;try{await api(`/conversations/${id}/messages`,{method:'DELETE'});toast('消息已清空');$('#modal').close()}catch(err){toast(err.message,true)}};
    form.querySelector('#conversation-delete').onclick=async()=>{if(!confirm('删除这个会话？'))return;try{await api(`/conversations/${id}`,{method:'DELETE'});deleted=true;if(state.conversation?.id===id)state.conversation=null;toast('会话已删除');$('#modal').close()}catch(err){toast(err.message,true)}};
  });
  if(renamed)toast('会话标题已更新');await refreshConversations(deleted?undefined:id);
}
async function openFragment(id){try{const item=await api(`/fragments/${id}`);await modal(item.document_title,`<div class="detail-grid"><span>位置</span><span>${esc(item.structural_path||'—')}${item.page_number?` · 第 ${item.page_number} 页`:''}</span><span>标签</span><span>${(item.document_tags||[]).map(x=>`<span class="tag">${esc(x)}</span>`).join(' ')||'—'}</span></div><div class="element"><pre>${esc(item.text)}</pre></div>`,async()=>{},'关闭')}catch(err){toast(err.message,true)}}
function parseSseChunk(buffer,onEvent){let boundary;while((boundary=buffer.indexOf('\n\n'))>=0){const frame=buffer.slice(0,boundary);buffer=buffer.slice(boundary+2);let type='message',data='';for(const line of frame.split('\n')){if(line.startsWith('event:'))type=line.slice(6).trim();if(line.startsWith('data:'))data+=line.slice(5).trim()}if(data){try{onEvent(type,JSON.parse(data))}catch{}}}return buffer}
async function streamTurn(path,content,retry=false){
  state.chatAbort=new AbortController();const c=state.conversation;let assistant={id:'pending',role:'assistant',status:'generating',content:'',citations:[],traces:[]};if(!retry)c.messages.push({id:`user-${Date.now()}`,role:'user',status:'completed',content,citations:[],traces:[]});c.messages.push(assistant);renderConversationPane();
  try{const res=await fetch(API+path,{method:'POST',credentials:'include',headers:{'Content-Type':'application/json'},body:JSON.stringify(content?{content}:{}),signal:state.chatAbort.signal});if(!res.ok){let d={};try{d=await res.json()}catch{}throw new Error(d.detail||`请求失败 (${res.status})`)}const reader=res.body.getReader(),decoder=new TextDecoder();let buffer='';while(true){const {value,done}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});buffer=parseSseChunk(buffer,(type,payload)=>{if(type==='message_created'){assistant.id=payload.assistant_message_id;const node=$('[data-message="pending"]');if(node)node.dataset.message=assistant.id}if(type==='answer_delta'){assistant.content+=payload.text||'';const node=$(`[data-message="${assistant.id}"] .chat-answer`);if(node)node.innerHTML=answerHtml(assistant.content)}if(['turn_failed','turn_cancelled'].includes(type)){assistant.status=type==='turn_failed'?'failed':'cancelled';assistant.error_message=payload.message||''}})}
  }catch(err){if(err.name!=='AbortError')toast(err.message,true)}finally{state.chatAbort=null;await refreshConversations(c.id)}
}
async function sendChatMessage(content){content=content.trim();if(!content||!state.conversation||state.chatAbort)return;await streamTurn(`/conversations/${state.conversation.id}/messages`,content)}
async function stopChat(){if(!state.conversation)return;try{await api(`/conversations/${state.conversation.id}/cancel`,{method:'POST'})}finally{state.chatAbort?.abort();state.chatAbort=null;await refreshConversations(state.conversation.id)}}
async function retryChat(messageId){if(!state.conversation||state.chatAbort)return;await streamTurn(`/conversations/${state.conversation.id}/messages/${messageId}/retry`,'',true)}
function applyChatSettings(){if(!state.conversation)return;const s=state.conversation.settings||{};$$('[name=chat_space]').forEach(x=>x.checked=(s.space_ids||[]).includes(x.value));for(const [name,key] of [['chat_keyword','use_keyword'],['chat_vector','use_vector'],['chat_graph','use_graph'],['chat_reranker','use_reranker']]){const el=$(`[name=${name}]`);if(el)el.checked=s[key]??true}}
function retrievalResultHtml(out){
  const trace=out.trace_summary||{},counts=out.channel_counts||out.channels||{},items=out.items||[];
  return `${out.warnings?.length?`<div class="warning">${out.warnings.map(esc).join('；')}</div>`:''}<div class="retrieval-metrics"><div><span>全文召回</span><b>${counts.keyword||0}</b></div><div><span>向量召回</span><b>${counts.vector||0}</b></div><div><span>图谱召回</span><b>${counts.graph||0}</b></div><div><span>最终结果</span><b>${items.length}</b></div><div><span>证据状态</span><b>${trace.evidence_insufficient?'不足':'充分'}</b></div></div>${table(['排名','文档与片段','召回通道','全文分','向量分','图谱分','融合分','重排分','操作'],items.map((x,index)=>`<tr><td><span class="rank-number">${x.rank||index+1}</span></td><td><b>${esc(x.title||'未命名文档')}</b><small class="retrieval-snippet">${esc((x.snippet||x.text||'').replace(/<[^>]+>/g,'').slice(0,220))}</small><small class="cell-subtitle">${esc(x.structural_path||'—')}${x.page_number?` · 第${x.page_number}页`:''}</small></td><td>${(x.channels||[]).map(channel=>`<span class="tag">${esc(channel)}</span>`).join(' ')||'—'}</td><td>${x.keyword_score==null?'—':Number(x.keyword_score).toFixed(4)}</td><td>${x.vector_score==null?'—':Number(x.vector_score).toFixed(4)}</td><td>${x.graph_score==null?'—':Number(x.graph_score).toFixed(4)}</td><td><b>${x.fused_score==null?'—':Number(x.fused_score).toFixed(4)}</b></td><td>${x.rerank_score==null?'—':Number(x.rerank_score).toFixed(4)}</td><td>${x.chunk_id?`<button class="small secondary" data-debug-fragment="${esc(x.chunk_id)}">查看片段</button>`:'—'}</td></tr>`))}`;
}
async function renderRetrievalDebug(){
  actions();await refreshLookups();const spaceChecks=state.spaces.map(x=>`<label class="check"><input type="checkbox" name="debug_space" value="${x.id}" checked>${esc(x.name)}</label>`).join('');
  page('检索调试',`<section class="panel retrieval-console"><form id="retrieval-debug-form"><div class="retrieval-query"><input name="query" placeholder="输入需要检索的问题" required><button type="submit">开始检索</button></div><details><summary>检索范围与通道</summary><div class="retrieval-settings"><div class="debug-space-list">${spaceChecks}</div><div class="debug-switches">${check('use_keyword','全文',true)}${check('use_vector','向量',true)}${check('use_graph','图谱',true)}${check('use_reranker','重排',true)}${field('top_k','返回数量',10,'number','min="1" max="50"')}</div></div></details></form></section><div id="retrieval-debug-result"><div class="panel empty">输入问题后查看各通道召回、融合分数和最终排序</div></div>`);
  $('#retrieval-debug-form').onsubmit=async event=>{
    event.preventDefault();const form=event.currentTarget,button=form.querySelector('[type=submit]'),data=formData(form),spaceIds=[...form.querySelectorAll('[name=debug_space]:checked')].map(x=>x.value);if(!spaceIds.length){toast('至少选择一个知识空间',true);return}
    if(state.retrievalAbort)state.retrievalAbort.abort();const controller=new AbortController();state.retrievalAbort=controller;let timedOut=false;const timeout=setTimeout(()=>{timedOut=true;controller.abort()},120000);button.disabled=true;button.textContent='检索中…';
    try{
      const out=await api('/search',{method:'POST',signal:controller.signal,body:{query:data.query,space_ids:spaceIds,top_k:Number(data.top_k),use_keyword:data.use_keyword,use_vector:data.use_vector,use_graph:data.use_graph,use_reranker:data.use_reranker,filters:{}}});
      const result=$('#retrieval-debug-result');if(state.view!=='retrieval'||!result)return;result.innerHTML=retrievalResultHtml(out);result.onclick=e=>{const id=e.target.closest('[data-debug-fragment]')?.dataset.debugFragment;if(id)openFragment(id)};
    }catch(err){
      if(err?.name==='AbortError'&&!timedOut)return;const result=$('#retrieval-debug-result');if(!result)return;const message=timedOut?'检索超时，请缩小范围或关闭重排后重试':err.message;toast(message,true);result.innerHTML=`<div class="panel empty error">${esc(message)}</div>`;
    }finally{clearTimeout(timeout);if(state.retrievalAbort===controller)state.retrievalAbort=null;if(button.isConnected){button.disabled=false;button.textContent='开始检索'}}
  };
}

const SERVICE_GUIDES={rest:{title:'REST / OpenAPI 接入手册',file:'rest-api.md'},mcp:{title:'MCP Server 接入手册',file:'mcp.md'},cli:{title:'传神智库 CLI 接入手册',file:'cli.md'},agent:{title:'DeepSeek Harness 接入手册',file:'agent.md'}};
function guideMarkdown(text){let html='',code=false,list=false;const closeList=()=>{if(list){html+='</ul>';list=false}};for(const raw of text.replace(/\r/g,'').split('\n')){if(raw.trim().startsWith('```')){closeList();html+=code?'</code></pre>':'<pre><code>';code=!code;continue}if(code){html+=`${esc(raw)}\n`;continue}const line=raw.trim();if(!line){closeList();continue}if(line.startsWith('### ')){closeList();html+=`<h3>${esc(line.slice(4))}</h3>`}else if(line.startsWith('## ')){closeList();html+=`<h2>${esc(line.slice(3))}</h2>`}else if(line.startsWith('# ')){closeList();html+=`<h1>${esc(line.slice(2))}</h1>`}else if(line.startsWith('- ')){if(!list){html+='<ul>';list=true}html+=`<li>${esc(line.slice(2))}</li>`}else{closeList();html+=`<p>${esc(line)}</p>`}}closeList();if(code)html+='</code></pre>';return html}
async function previewServiceGuide(type){const guide=SERVICE_GUIDES[type];if(!guide)return;const response=await fetch(`/assets/manuals/${guide.file}`,{cache:'no-store'});if(!response.ok)throw new Error('接入手册加载失败');const text=await response.text(),dlg=$('#modal');dlg.classList.add('guide-modal');$('#modal-cancel').classList.add('hidden');try{await modal(guide.title,`<article class="guide-preview">${guideMarkdown(text)}</article>`,async()=>{},'关闭')}finally{dlg.classList.remove('guide-modal');$('#modal-cancel').classList.remove('hidden')}}
async function renderIntegrations(){
  actions();page('服务开放',`<div class="integration-grid"><section class="integration-card"><span class="integration-icon">API</span><div><b>REST / OpenAPI</b><p>统一调用混合检索、对话、片段、画像和图谱能力。</p><code>http://localhost:8080/api/v1</code></div><div class="integration-actions"><button type="button" data-service-guide="rest">接入手册</button><a class="button-link secondary" href="/docs" target="_blank" rel="noopener">API 文档</a></div></section><section class="integration-card"><span class="integration-icon">MCP</span><div><b>MCP Server</b><p>面向支持 MCP 的模型和智能体开放知识工具。</p><code>http://localhost:8091/mcp</code></div><div class="integration-actions"><button type="button" data-service-guide="mcp">接入手册</button><span class="integration-status">Docker 内服务 · 8091</span></div></section><section class="integration-card"><span class="integration-icon">CLI</span><div><b>传神智库 CLI</b><p>用于搜索知识、发起对话、同步数据源和查询任务。</p><pre>chuanshen --help\nchuanshen search &quot;查询内容&quot;</pre></div><div class="integration-actions"><button type="button" data-service-guide="cli">接入手册</button><span class="integration-status">随平台镜像交付</span></div></section><section class="integration-card"><span class="integration-icon">Agent</span><div><b>DeepSeek Harness</b><p>通过独立运行时和 Knowledge Tool 协议驱动多轮知识问答。</p><code>agent-runtime:8090</code></div><div class="integration-actions"><button type="button" data-service-guide="agent">接入手册</button><span class="integration-status">仅 Docker 内网访问</span></div></section></div>`);
  $('#content').onclick=async e=>{const button=e.target.closest('[data-service-guide]');if(!button)return;button.disabled=true;try{await previewServiceGuide(button.dataset.serviceGuide)}catch(err){toast(err.message,true)}finally{if(button.isConnected)button.disabled=false}};
}

async function renderSearch(){
  actions('<button id="conversation-new">新建会话</button>');await refreshLookups();
  page('智能问答',`<div class="chat-layout"><aside class="conversation-sidebar"><div id="conversation-list"></div></aside><section class="chat-workspace"><div class="chat-settings"><details><summary>检索范围与高级选项</summary><div class="chat-setting-body"><div class="chat-space-list">${state.spaces.map(x=>`<label class="check"><input type="checkbox" name="chat_space" value="${x.id}">${esc(x.name)}</label>`).join('')}</div><div class="chat-switches">${check('chat_keyword','全文',true)}${check('chat_vector','向量',true)}${check('chat_graph','图谱',true)}${check('chat_reranker','重排',true)}</div></div></details></div><div id="chat-main"></div></section></div>`,'chat-view');
  $('#conversation-new').onclick=newConversation;
  $('#conversation-list').onclick=e=>{const row=e.target.closest('[data-conversation]');if(!row)return;if(e.target.closest('.conversation-more'))conversationMenu(row.dataset.conversation);else loadConversation(row.dataset.conversation)};
  $('.chat-settings').onchange=async()=>{if(!state.conversation)return;const body={space_ids:[...$$('[name=chat_space]:checked')].map(x=>x.value),use_keyword:$('[name=chat_keyword]').checked,use_vector:$('[name=chat_vector]').checked,use_graph:$('[name=chat_graph]').checked,use_reranker:$('[name=chat_reranker]').checked};try{await api(`/conversations/${state.conversation.id}`,{method:'PUT',body});state.conversation.settings={...(state.conversation.settings||{}),...body}}catch(err){toast(err.message,true)}};
  await refreshConversations();applyChatSettings();
}

function analysisSpaceChecks(selected=[]){return `<label class="field"><span>知识空间</span><div class="analysis-space-checks">${state.spaces.map(x=>`<label class="check"><input type="checkbox" name="analysis_space" value="${x.id}" ${selected.includes(x.id)?'checked':''}>${esc(x.name)}</label>`).join('')}</div></label>`}
function analysisRuleSetForm(x={}){return `<div class="field-row">${field('name','名称',x.name||'','text','required')}${field('category','分类',x.category||'通用','text','required')}</div>`+area('description','描述',x.description||'')+analysisSpaceChecks(x.space_ids||[])+`<div class="field-row">${check('auto_run','自动运行',x.auto_run||false)}${check('auto_publish','自动发布',x.auto_publish||false)}</div>`+check('enabled','启用',x.enabled??true)}
async function editAnalysisRuleSet(x){await refreshLookups();const ok=await modal(x?'编辑规则集':'新增规则集',analysisRuleSetForm(x),async(d,form)=>{d.space_ids=[...form.querySelectorAll('[name=analysis_space]:checked')].map(el=>el.value);delete d.analysis_space;if(!d.space_ids.length)throw new Error('至少选择一个知识空间');await api(x?`/analysis/rule-sets/${x.id}`:'/analysis/rule-sets',{method:x?'PUT':'POST',body:d})});if(ok){toast('规则集已保存');renderAnalysis()}}
function analysisRuleForm(x={}){const definition=x.definition||{},conditions=definition.conditions?.length?definition.conditions:[{predicate:'',subject:'X',object:'Y'}],head=definition.conclusion||{predicate:'',subject:'X',object:'Y'};return field('name','规则名称',x.name||'','text','required')+area('description','描述',x.description||'')+`<label class="field"><span>满足以下条件</span><div id="analysis-condition-list">${conditions.map((item,index)=>analysisConditionRow(item,index)).join('')}</div><button id="analysis-condition-add" class="secondary small" type="button">添加条件</button></label><label class="field"><span>推导结论</span><div class="analysis-rule-row conclusion">${field('head_predicate','关系',head.predicate||'','text','required')}${field('head_subject','主体',head.subject||'X','text','required')}${field('head_object','客体',head.object||'Y','text','required')}</div></label><div class="field-row">${field('priority','优先级',x.priority??100,'number','required min="0" max="10000"')}${field('confidence','规则置信度',x.confidence??1,'number','required min="0" max="1" step="0.01"')}</div>`+check('enabled','启用',x.enabled??true)}
function analysisConditionRow(item={},index=0){return `<div class="analysis-rule-row" data-condition><input name="condition_predicate_${index}" value="${esc(item.predicate||'')}" placeholder="关系" required><input name="condition_subject_${index}" value="${esc(item.subject||'X')}" placeholder="主体或变量" required><input name="condition_object_${index}" value="${esc(item.object||'Y')}" placeholder="客体或变量" required><button class="secondary small" type="button" data-condition-remove>移除</button></div>`}
async function editAnalysisRule(ruleSet,x){const ok=await modal(x?'编辑规则':'新增规则',analysisRuleForm(x),async(d,form)=>{const conditions=[...form.querySelectorAll('[data-condition]')].map(row=>({predicate:row.children[0].value.trim(),subject:row.children[1].value.trim(),object:row.children[2].value.trim()}));if(!conditions.length)throw new Error('至少配置一个条件');const body={name:d.name,description:d.description,definition:{conditions,conclusion:{predicate:d.head_predicate,subject:d.head_subject,object:d.head_object}},priority:Number(d.priority),confidence:Number(d.confidence),enabled:d.enabled};await api(x?`/analysis/rules/${x.id}`:`/analysis/rule-sets/${ruleSet.id}/rules`,{method:x?'PUT':'POST',body})},'保存',form=>{const list=form.querySelector('#analysis-condition-list');const bindRemove=()=>form.querySelectorAll('[data-condition-remove]').forEach(button=>button.onclick=()=>{if(list.children.length>1)button.closest('[data-condition]').remove()});bindRemove();form.querySelector('#analysis-condition-add').onclick=()=>{list.insertAdjacentHTML('beforeend',analysisConditionRow({},list.children.length));bindRemove()}});if(ok){toast('规则已保存');renderAnalysis()}}
async function viewRuleVersions(rule){const rows=await api(`/analysis/rules/${rule.id}/versions`);await modal(`${rule.name} · 版本`,table(['版本','规则 DSL','创建时间'],rows.map(x=>`<tr><td>V${x.version}</td><td class="mono">${esc(x.dsl)}</td><td>${fmtDate(x.created_at)}</td></tr>`)),async()=>{},'关闭')}
function analysisScenarioForm(sets,x={}){return `<div class="field-row">${field('name','场景名称',x.name||'','text','required')}${field('category','分类',x.category||'通用','text','required')}</div>`+area('description','描述',x.description||'')+selectField('rule_set_id','规则集',opt(sets,'请选择'),x.rule_set_id||'','required')+analysisSpaceChecks(x.space_ids||[])+check('enabled','启用',x.enabled??true)}
async function editAnalysisScenario(sets,x){await refreshLookups();const ok=await modal(x?'编辑场景':'新增场景',analysisScenarioForm(sets,x),async(d,form)=>{d.space_ids=[...form.querySelectorAll('[name=analysis_space]:checked')].map(el=>el.value);delete d.analysis_space;if(!d.space_ids.length)throw new Error('至少选择一个知识空间');await api(x?`/analysis/scenarios/${x.id}`:'/analysis/scenarios',{method:x?'PUT':'POST',body:d})});if(ok){toast('场景已保存');renderAnalysis()}}
async function startAnalysisRun(ruleSet,scenario=null){const allowed=(scenario?.space_ids?.length?scenario.space_ids:ruleSet.space_ids)||[];const body=analysisSpaceChecks(allowed)+`<div class="field-row">${selectField('mode','运行方式',[['preview','预览'],['publish','发布推导事实']],'preview')}${field('max_results','最大结果数',1000,'number','required min="1" max="10000"')}</div>`;const ok=await modal('运行知识推理',body,async(d,form)=>{d.space_ids=[...form.querySelectorAll('[name=analysis_space]:checked')].map(el=>el.value);delete d.analysis_space;d.rule_set_id=ruleSet.id;d.scenario_id=scenario?.id||null;d.max_results=Number(d.max_results);if(!d.space_ids.length)throw new Error('至少选择一个知识空间');await api('/analysis/inference-runs',{method:'POST',body:d})},'开始运行');if(ok){toast('推理任务已提交');state.analysisTab='results';renderAnalysis()}}
function analysisTabs(){return `<div class="analysis-tabs">${[['scenarios','场景分析'],['rules','规则中心'],['results','推理结果'],['query','高级查询']].map(([id,label])=>`<button class="secondary ${state.analysisTab===id?'active':''}" data-analysis-tab="${id}">${label}</button>`).join('')}</div><div id="analysis-body"></div>`}
async function renderAnalysis(){await refreshLookups();const sets=await api('/analysis/rule-sets');page('知识分析',analysisTabs(),'analysis-view');$$('[data-analysis-tab]').forEach(button=>button.onclick=()=>{state.analysisTab=button.dataset.analysisTab;renderAnalysis()});if(state.analysisTab==='rules')await renderAnalysisRules(sets);else if(state.analysisTab==='results')await renderAnalysisResults(sets);else if(state.analysisTab==='query')await renderAnalysisQuery();else await renderAnalysisScenarios(sets)}
async function renderAnalysisScenarios(sets){actions('<button id="analysis-scenario-add">新增场景</button>');const rows=await api('/analysis/scenarios');const names=Object.fromEntries(sets.map(x=>[x.id,x.name]));$('#analysis-body').innerHTML=table(['名称','分类','规则集','知识空间','状态','操作'],rows.map(x=>`<tr><td>${esc(x.name)}</td><td>${esc(x.category)}</td><td>${esc(names[x.rule_set_id]||'—')}</td><td>${esc((x.space_ids||[]).map(id=>state.spaces.find(s=>s.id===id)?.name||id).join('、'))}</td><td>${status(x.enabled?'available':'unavailable')}</td><td class="actions">${btn('运行','scenario-run',x.id)}${btn('编辑','scenario-edit',x.id)}${btn('删除','scenario-delete',x.id,'danger')}</td></tr>`));$('#analysis-scenario-add').onclick=()=>editAnalysisScenario(sets);$('#analysis-body').onclick=async e=>{const b=e.target.closest('[data-action]');if(!b)return;const x=rows.find(row=>row.id===b.dataset.id);const set=sets.find(row=>row.id===x?.rule_set_id);try{if(b.dataset.action==='scenario-run'){if(!set)throw new Error('场景未绑定有效规则集');await startAnalysisRun(set,x)}if(b.dataset.action==='scenario-edit')editAnalysisScenario(sets,x);if(b.dataset.action==='scenario-delete'&&confirm(`删除场景 ${x.name}？`)){await api(`/analysis/scenarios/${x.id}`,{method:'DELETE'});renderAnalysis()}}catch(err){toast(err.message,true)}}}
async function renderAnalysisRules(sets){if(!sets.some(x=>x.id===state.analysisRuleSetId))state.analysisRuleSetId=sets[0]?.id||null;const selected=sets.find(x=>x.id===state.analysisRuleSetId);const rules=selected?await api(`/analysis/rule-sets/${selected.id}/rules`):[];actions(`<button id="analysis-set-add">新增规则集</button>${selected?'<button id="analysis-rule-add">新增规则</button>':''}`);$('#analysis-body').innerHTML=`<div class="analysis-split"><section>${table(['规则集','分类','规则数','状态','操作'],sets.map(x=>`<tr class="${x.id===selected?.id?'selected-row':''}"><td><button class="link-button" data-action="set-select" data-id="${x.id}">${esc(x.name)}</button></td><td>${esc(x.category)}</td><td>${x.rule_count}</td><td>${status(x.enabled?'available':'unavailable')}</td><td class="actions">${btn('运行','set-run',x.id)}${btn('编辑','set-edit',x.id)}${btn('删除','set-delete',x.id,'danger')}</td></tr>`))}</section><section>${selected?table(['规则','DSL','优先级','版本','状态','操作'],rules.map(x=>`<tr><td>${esc(x.name)}</td><td class="truncate mono">${esc(x.dsl)}</td><td>${x.priority}</td><td>V${x.current_version}</td><td>${status(x.enabled?'available':'unavailable')}</td><td class="actions">${btn('版本','rule-versions',x.id)}${btn('编辑','rule-edit',x.id)}${btn('删除','rule-delete',x.id,'danger')}</td></tr>`)):'<div class="panel empty">请先创建规则集</div>'}</section></div>`;$('#analysis-set-add').onclick=()=>editAnalysisRuleSet();if(selected)$('#analysis-rule-add').onclick=()=>editAnalysisRule(selected);$('#analysis-body').onclick=async e=>{const b=e.target.closest('[data-action]');if(!b)return;const set=sets.find(x=>x.id===b.dataset.id),rule=rules.find(x=>x.id===b.dataset.id);try{if(b.dataset.action==='set-select'){state.analysisRuleSetId=b.dataset.id;renderAnalysis()}if(b.dataset.action==='set-run')startAnalysisRun(set);if(b.dataset.action==='set-edit')editAnalysisRuleSet(set);if(b.dataset.action==='set-delete'&&confirm(`删除规则集 ${set.name}？`)){await api(`/analysis/rule-sets/${set.id}`,{method:'DELETE'});state.analysisRuleSetId=null;renderAnalysis()}if(b.dataset.action==='rule-versions')viewRuleVersions(rule);if(b.dataset.action==='rule-edit')editAnalysisRule(selected,rule);if(b.dataset.action==='rule-delete'&&confirm(`删除规则 ${rule.name}？`)){await api(`/analysis/rules/${rule.id}`,{method:'DELETE'});renderAnalysis()}}catch(err){toast(err.message,true)}}}
async function viewInferenceRun(row){const detail=await api(`/analysis/inference-runs/${row.id}`),rules=await api(`/analysis/rule-sets/${row.rule_set_id}/rules`),ruleNames=Object.fromEntries(rules.map(x=>[x.id,x.name]));const body=`<div class="source-summary"><div><span>状态</span><b>${esc(detail.status)}</b></div><div><span>进度</span><b>${detail.progress}%</b></div><div><span>结果</span><b>${detail.items.length}</b></div><div><span>模式</span><b>${esc(detail.mode)}</b></div></div>`+table(['结论','规则','置信度','状态','依据'],detail.items.map(x=>`<tr><td><b>${esc(x.subject_name)}</b> <span class="analysis-predicate">${esc(x.predicate)}</span> <b>${esc(x.object_name||'—')}</b></td><td>${esc(ruleNames[x.rule_id]||x.rule_id)}</td><td>${(Number(x.confidence)*100).toFixed(1)}%</td><td>${status(x.status)}</td><td><details><summary>${x.evidence.length} 条</summary>${x.evidence.map(item=>`<div class="analysis-proof">${esc(item.predicate||item.predicate_token||'推导前提')} · ${esc(item.source_fact_id||'推导事实')}</div>`).join('')}</details></td></tr>`));await modal('推理结果',body,async()=>{},'关闭')}
async function renderAnalysisResults(sets){actions('<button id="analysis-results-refresh">刷新</button>');const rows=await api('/analysis/inference-runs'),names=Object.fromEntries(sets.map(x=>[x.id,x.name]));$('#analysis-body').innerHTML=table(['时间','规则集','方式','范围','进度','状态','结果','操作'],rows.map(x=>`<tr><td>${fmtDate(x.created_at)}</td><td>${esc(names[x.rule_set_id]||'—')}</td><td>${x.mode==='publish'?'发布':'预览'}</td><td>${(x.space_ids||[]).length} 个空间</td><td>${progress(x.progress)}</td><td>${status(x.status)}</td><td>${x.metrics?.persisted_results??'—'}</td><td class="actions">${btn('查看','run-view',x.id)}${x.mode==='publish'&&x.status==='succeeded'?btn('回滚','run-rollback',x.id,'danger'):''}</td></tr>`));$('#analysis-results-refresh').onclick=renderAnalysis;$('#analysis-body').onclick=async e=>{const b=e.target.closest('[data-action]');if(!b)return;const x=rows.find(row=>row.id===b.dataset.id);try{if(b.dataset.action==='run-view')viewInferenceRun(x);if(b.dataset.action==='run-rollback'&&confirm('撤销该次运行发布的推导事实？')){await api(`/analysis/inference-runs/${x.id}/rollback`,{method:'POST'});toast('已回滚');renderAnalysis()}}catch(err){toast(err.message,true)}};if(rows.some(x=>['queued','running'].includes(x.status)))state.analysisTimer=setTimeout(()=>state.view==='analysis'&&state.analysisTab==='results'&&renderAnalysis(),1500)}
function analysisQueryWorkspace(saved){const defaultQuery='SELECT ?s ?p ?o\nWHERE {\n  ?s ?p ?o\n}\nLIMIT 50';return `<div class="analysis-query-layout"><aside class="panel"><div class="toolbar"><b>保存的查询</b><span class="grow"></span><button id="analysis-query-save" class="small">保存</button></div><div class="saved-query-list">${saved.length?saved.map(x=>`<div class="saved-query-item" data-saved-query="${x.id}"><button class="link-button" data-action="query-load" data-id="${x.id}">${esc(x.name)}</button><span>${btn('编辑','query-edit',x.id)}${btn('删除','query-delete',x.id,'danger')}</span></div>`).join(''):'<div class="empty">暂无查询</div>'}</div></aside><section class="panel"><div class="analysis-query-editor">${analysisSpaceChecks(state.spaces.map(x=>x.id))}<label class="field"><span>SPARQL</span><textarea id="analysis-sparql" class="code-editor">${esc(defaultQuery)}</textarea></label><div><button id="analysis-query-run">执行查询</button></div></div><div id="analysis-query-result" class="analysis-query-result"><div class="empty">等待执行</div></div></section></div>`}
async function saveAnalysisQuery(saved,x=null){const current=$('#analysis-sparql')?.value||x?.query_text||'',spaces=[...$$('[name=analysis_space]:checked')].map(el=>el.value);const ok=await modal(x?'编辑查询':'保存查询',field('name','名称',x?.name||'','text','required')+check('enabled','启用',x?.enabled??true),async d=>api(x?`/analysis/saved-queries/${x.id}`:'/analysis/saved-queries',{method:x?'PUT':'POST',body:{...d,query_type:'sparql',space_ids:x?x.space_ids:spaces,query_text:x?x.query_text:current,config:x?.config||{}}}));if(ok){toast('查询已保存');renderAnalysis()}}
async function renderAnalysisQuery(){actions();const saved=await api('/analysis/saved-queries');$('#analysis-body').innerHTML=analysisQueryWorkspace(saved);$('#analysis-query-save').onclick=()=>saveAnalysisQuery(saved);$('#analysis-query-run').onclick=async()=>{const button=$('#analysis-query-run'),spaces=[...$$('[name=analysis_space]:checked')].map(el=>el.value),query=$('#analysis-sparql').value.trim();if(!spaces.length){toast('至少选择一个知识空间',true);return}button.disabled=true;button.textContent='查询中…';try{const result=await api('/analysis/sparql',{method:'POST',body:{space_ids:spaces,query}}),rows=result.rows||[],columns=result.columns||[];$('#analysis-query-result').innerHTML=`<div class="toolbar"><span>${result.total} 条</span><span>${result.duration_ms} ms</span><span>${result.projection.triples} 个三元组</span></div>`+table(columns,rows.map(row=>`<tr>${columns.map(column=>`<td class="mono">${esc(row[column]??'—')}</td>`).join('')}</tr>`))}catch(err){toast(err.message,true);$('#analysis-query-result').innerHTML=`<div class="empty error">${esc(err.message)}</div>`}finally{button.disabled=false;button.textContent='执行查询'}};$('#analysis-body').onclick=async e=>{const b=e.target.closest('[data-action]');if(!b)return;const x=saved.find(row=>row.id===b.dataset.id);try{if(b.dataset.action==='query-load'){state.spaces.forEach(space=>{const input=$(`[name=analysis_space][value="${space.id}"]`);if(input)input.checked=(x.space_ids||[]).includes(space.id)});$('#analysis-sparql').value=x.query_text}if(b.dataset.action==='query-edit')saveAnalysisQuery(saved,x);if(b.dataset.action==='query-delete'&&confirm(`删除查询 ${x.name}？`)){await api(`/analysis/saved-queries/${x.id}`,{method:'DELETE'});renderAnalysis()}}catch(err){toast(err.message,true)}}}

async function renderAudits(){actions();const rows=await api('/audit-events');page('审计日志',table(['时间','动作','对象','对象 ID','操作者','详情'],rows.map(x=>`<tr><td>${fmtDate(x.created_at)}</td><td class="mono">${esc(x.action)}</td><td>${esc(x.object_type)}</td><td class="mono">${esc(x.object_id||'—')}</td><td class="mono">${esc(x.actor_id||'—')}</td><td class="truncate mono">${esc(JSON.stringify(x.detail||{}))}</td></tr>`)))}

window.addEventListener('popstate',()=>{if(state.user)go(location.hash.slice(1)||'dashboard',false)});
(async()=>{try{state.user=await api('/auth/me');showShell();await go(location.hash.slice(1)||'dashboard',false)}catch{showLogin()}})();
